import assert from 'node:assert/strict';
/** Business delta only: bound own App and non-agent synthetic browser task are prerequisites.
 * No DOM/store writes, synthetic events, focus(), business RPC or native input.
 * Renderer focus emulation is caller-owned presentation fixture, not OS focus proof. */
export const uiObservation=`(()=>{const w=document.querySelector('.bw-workspace');const panel=document.querySelector('.bw-downloads[role="region"][aria-label="下载"]');return{taskId:w?.dataset.browserTask??null,menu:!!document.querySelector('.bw-menu[role="menu"]'),panel:!!panel,panelText:panel?.innerText??null,activeTag:document.activeElement?.tagName??null,activeRole:document.activeElement?.getAttribute('role')??null,bodyActive:document.activeElement===document.body,documentHasFocus:document.hasFocus(),downloadButtonExpanded:document.querySelector('.bw-download-trigger')?.getAttribute('aria-expanded')??null};})()`;
export function controlGeometry(selector,text){return `(()=>{const es=[...document.querySelectorAll(${JSON.stringify(selector)})].filter(e=>{const r=e.getBoundingClientRect();return r.width>0&&r.height>0${text===undefined?'':`&&e.textContent.trim()===${JSON.stringify(text)}`}});if(es.length!==1)throw Error('Exactly one visible control required');const e=es[0];e.scrollIntoView({behavior:'instant',block:'nearest'});const r=e.getBoundingClientRect(),x=r.x+r.width/2,y=r.y+r.height/2;if(e.matches(':disabled')||!e.contains(document.elementFromPoint(x,y)))throw Error('Control blocked');return{x,y};})()`;}
export async function downloadsEscape({app,taskId,assertOwn,save,screenshot}){
 assert(app&&typeof taskId==='string'&&typeof assertOwn==='function'&&typeof save==='function');
 const report={scope:'015 Browser downloads menu body-focus Escape UI regression only',startedAt:new Date().toISOString(),actions:[],observations:[]};
 const snapshot=async phase=>{await assertOwn();const row={phase,at:new Date().toISOString(),ui:await app.evaluate(uiObservation)};report.observations.push(row);await save(report);assert.equal(row.ui.taskId,taskId);return row.ui;};
 async function wait(fn,ms=5000){const end=Date.now()+ms;while(Date.now()<end){const value=await fn();if(value)return value;await new Promise(r=>setTimeout(r,25));}throw Error('Bounded real UI condition timeout');}
 async function click(selector,text){
  const expression=controlGeometry(selector,text);
  await assertOwn();const p=await app.evaluate(expression);await app.evaluate('new Promise(r=>requestAnimationFrame(r))');assert.deepEqual(await app.evaluate(expression),p);await assertOwn();
  for(const type of ['mouseMoved','mousePressed','mouseReleased'])await app.cdp('Input.dispatchMouseEvent',{type,...p,...(type==='mouseMoved'?{}:{button:'left',clickCount:1})});
  report.actions.push({kind:'click',selector,text,at:new Date().toISOString()});await save(report);
 }
 try{
  report.initial=await snapshot('initial');
  report.downloadsBefore=(await app.invoke('browser.snapshot',{taskId})).downloads;await save(report);assert(Array.isArray(report.downloadsBefore)&&report.downloadsBefore.length>0,'Precondition requires existing synthetic download record');assert(report.downloadsBefore.every(x=>x.state!=='progress'),'No active transfer in this UI-only regression');
  // Automatic opening is allowed by production; dismiss it via real UI first.
  if(report.initial.panel){await click('[aria-label="收起下载列表"]');await wait(async()=>!(await app.evaluate(uiObservation)).panel);}
  assert.equal((await app.evaluate(uiObservation)).menu,false,'Precondition: no earlier menu');
  await click('[aria-label="浏览器菜单"]');await wait(async()=>(await app.evaluate(uiObservation)).menu);await snapshot('menu-open');
  await click('.bw-menu [role="menuitem"]','下载');
  // No focus relocation; the clicked menu item naturally unmounts.
  await wait(async()=>{const u=await app.evaluate(uiObservation);return u.panel&&!u.menu?u:null;});report.beforeEscape=await snapshot('download-panel-menu-item-unmounted');
  assert.equal(report.beforeEscape.bodyActive,true,'Menu item removal must naturally leave actual focus on body');
  if(screenshot)await screenshot('downloads-before-escape.png');
  await assertOwn();
  for(const type of ['keyDown','keyUp'])await app.cdp('Input.dispatchKeyEvent',{type,key:'Escape',code:'Escape',windowsVirtualKeyCode:27,nativeVirtualKeyCode:53});
  report.actions.push({kind:'single-Escape',source:'CDP Input to exact own target',at:new Date().toISOString()});await save(report);
  await wait(async()=>!(await app.evaluate(uiObservation)).panel,2500);report.afterEscape=await snapshot('after-escape-closed');
  assert.equal(report.afterEscape.menu,false);assert.equal(report.afterEscape.bodyActive,true,'Do not steal Renderer focus from body');assert.equal(report.afterEscape.downloadButtonExpanded,'false');
  report.downloadsAfter=(await app.invoke('browser.snapshot',{taskId})).downloads;await save(report);assert.deepEqual(report.downloadsAfter,report.downloadsBefore,'Viewing/closing must not change download records');
  if(screenshot)await screenshot('downloads-after-escape.png');report.status='DOWNLOAD_MENU_BODY_ESCAPE_CLOSED_NO_FOCUS_RELOCATION_OBSERVED_PENDING_ROOT';
 }catch(e){report.status='FAILED';report.error={message:e.message,stack:e.stack};try{await snapshot('failure');}catch{}throw e;}
 finally{report.finishedAt=new Date().toISOString();await save(report);}
 return report;
}

import type {IpcMainInvokeEvent} from 'electron';
import {z} from 'zod';
import {createScopedRPCController} from '@shared/ipc/rpc';
import {browserTaskInput,browserTabInput,browserNavigationInput,browserActionInput,browserPlacementInput} from '@shared/browser-workspace';
import type {BrowserService} from './service';
import {BrowserError} from './errors';
import {browserSettingsSchema} from '@shared/browser-settings';
export function createBrowserController(service:BrowserService|undefined,trusted:(event:IpcMainInvokeEvent)=>boolean){
  const host=(event:IpcMainInvokeEvent)=>{
    if(!event?.sender||event.sender.isDestroyed()||event.senderFrame!==event.sender.mainFrame||!trusted(event))throw new BrowserError('BROWSER_UNAVAILABLE','浏览器界面操作只允许可信主窗口');
    if(!service)throw new BrowserError('BROWSER_UNAVAILABLE','浏览器组件尚未就绪');return service;
  };
  const ui=(event:IpcMainInvokeEvent)=>host(event).workspace;
  return createScopedRPCController({
    focusChrome:event=>{ui(event);event.sender.focus();},
    snapshot:(event,input:{taskId:string})=>ui(event).snapshot(browserTaskInput.parse(input).taskId),
    create:(event,input:{taskId:string})=>ui(event).create(browserTaskInput.parse(input).taskId),
    select:(event,input:{taskId:string;tabId:string|null})=>{const w=ui(event),v=browserTaskInput.extend({tabId:z.string().uuid().nullable()}).strict().parse(input);return w.select(v.taskId,v.tabId);},
    navigate:(event,input:{taskId:string;tabId:string;address:string})=>{const w=ui(event),v=browserNavigationInput.parse(input);return w.navigate(v.taskId,v.tabId,v.address);},
    action:(event,input:{taskId:string;tabId:string;action:'reload'|'hard-reload'|'stop'|'back'|'forward'|'focus'})=>{const w=ui(event),v=browserActionInput.parse(input);return w.action(v.taskId,v.tabId,v.action);},
    placement:(event,input:{taskId:string;tabId:string;rect:Electron.Rectangle|null})=>{const w=ui(event),v=browserPlacementInput.parse(input);return w.placement(v.taskId,v.tabId,v.rect);},
    close:(event,input:{taskId:string;tabId:string})=>{const w=ui(event),v=browserTabInput.parse(input);return w.close(v.taskId,v.tabId);},
    reopen:(event,input:{taskId:string})=>ui(event).reopen(browserTaskInput.parse(input).taskId),
    find:(event,input:{taskId:string;tabId:string;text:string;forward:boolean;next:boolean})=>{const w=ui(event),v=browserTabInput.extend({text:z.string(),forward:z.boolean(),next:z.boolean()}).strict().parse(input);return w.find(v.taskId,v.tabId,v.text,v.forward,v.next);},
    external:(event,input:{taskId:string;id:string;allow:boolean})=>{const w=ui(event),v=browserTaskInput.extend({id:z.string().uuid(),allow:z.boolean()}).strict().parse(input);return w.confirmExternal(v.taskId,v.id,v.allow);},
    overlay:(event,input:{taskId:string;tabId:string;open:boolean;capture?:boolean;owner?:string})=>{const w=ui(event),v=browserTabInput.extend({open:z.boolean(),capture:z.boolean().optional(),owner:z.string().min(1).max(128).optional()}).strict().parse(input);return w.overlay(v.taskId,v.tabId,v.open,v.capture,v.owner);},
    preferences:(event,input:{taskId:string})=>host(event).preferences(browserTaskInput.parse(input).taskId),
    settings:(event,input:{taskId:string;searchEngine?:'bing'|'google'|'duckduckgo'|'kagi';identity?:'clean'|'native'})=>{
      const s=host(event),v=browserTaskInput.extend({searchEngine:browserSettingsSchema.shape.searchEngine.optional(),identity:browserSettingsSchema.shape.identity.optional()}).strict().parse(input);s.workspace.snapshot(v.taskId);
      if(v.searchEngine!==undefined)s.settings.setSearchEngine(v.searchEngine);if(v.identity!==undefined)s.settings.setIdentity(v.identity);return s.preferences(v.taskId);
    },
    clearArtifacts:(event,input:{taskId:string;confirmed:true})=>{const s=host(event),v=browserTaskInput.extend({confirmed:z.literal(true)}).strict().parse(input);return s.clearArtifacts(v.taskId);},
    continueCertificate:(event,input:{taskId:string;tabId:string;challengeId:string})=>{const s=host(event),v=browserTabInput.extend({challengeId:z.string().uuid()}).strict().parse(input);return s.continueCertificate(v.taskId,v.tabId,v.challengeId);},
    profileSiteStates:(event,input:{taskId:string})=>host(event).profileSiteStates(browserTaskInput.parse(input).taskId),
    accessState:event=>host(event).accessState(),
    respondAccess:(event,input:{id:string;allow:boolean;mode?:'observe'|'control'})=>{const s=host(event),v=z.object({id:z.uuid(),allow:z.boolean(),mode:z.enum(['observe','control']).optional()}).strict().parse(input);s.respondAccess(v.id,v.allow,v.mode);},
    revokeAccess:(event,input:{id:string})=>{const s=host(event),v=z.object({id:z.uuid()}).strict().parse(input);s.revokeAccess(v.id);},
    pause:(event,input:{taskId:string;paused:boolean})=>{const s=host(event),v=browserTaskInput.extend({paused:z.boolean()}).strict().parse(input);return s.pauseFromUi(v.taskId,v.paused);},
    createProfile:(event,input:{taskId:string;label:string})=>{const s=host(event),v=browserTaskInput.extend({label:z.string().trim().min(1).max(120)}).strict().parse(input);return s.createProfile(v.taskId,v.label);},
    cloneProfile:(event,input:{taskId:string;profileId:string})=>{const s=host(event),v=browserTaskInput.extend({profileId:z.string()}).strict().parse(input);return s.cloneProfile(v.taskId,v.profileId);},
    useProfile:(event,input:{taskId:string;tabId:string;profileId:string})=>{const s=host(event),v=browserTabInput.extend({profileId:z.string()}).strict().parse(input);return s.useProfile(v.taskId,v.tabId,v.profileId);},
    deleteProfile:(event,input:{taskId:string;profileId:string;confirmed:true})=>{const s=host(event),v=browserTaskInput.extend({profileId:z.string(),confirmed:z.literal(true)}).strict().parse(input);return s.deleteProfile(v.taskId,v.profileId);},
    importCookieSources:(event,input:{taskId:string})=>host(event).importCookieSources(browserTaskInput.parse(input).taskId),
    importCookies:(event,input:{taskId:string;profileId:string;sourceId:string;confirmed:true})=>{const s=host(event),v=browserTaskInput.extend({profileId:z.string(),sourceId:z.string().regex(/^[a-f0-9]{64}$/),confirmed:z.literal(true)}).strict().parse(input);return s.importCookies(v.taskId,v.profileId,v.sourceId);},
    recoverCookies:(event,input:{taskId:string;profileId:string})=>{const s=host(event),v=browserTaskInput.extend({profileId:z.string()}).strict().parse(input);return s.recoverCookies(v.taskId,v.profileId);},
    clearCookies:(event,input:{taskId:string;profileId:string;confirmed:true})=>{const s=host(event),v=browserTaskInput.extend({profileId:z.string(),confirmed:z.literal(true)}).strict().parse(input);return s.clearCookies(v.taskId,v.profileId);},
    revokeCertificate:(event,input:{taskId:string;profileId:string;host:string})=>{const s=host(event),v=browserTaskInput.extend({profileId:z.string(),host:z.string()}).strict().parse(input);s.revokeCertificate(v.taskId,v.profileId,v.host);return s.profileSiteStates(v.taskId);},
    respondPermission:(event,input:{taskId:string;id:string;allow:boolean})=>{const s=host(event),v=browserTaskInput.extend({id:z.string().uuid(),allow:z.boolean()}).strict().parse(input);s.respondPermission(v.taskId,v.id,v.allow);},
    revokePermission:(event,input:{taskId:string;profileId:string;origin:string;permission:string})=>{const s=host(event),v=browserTaskInput.extend({profileId:z.string(),origin:z.string(),permission:z.string()}).strict().parse(input);s.revokePermission(v.taskId,v.profileId,v.origin,v.permission);return s.profileSiteStates(v.taskId);},
    downloadAction:(event,input:{taskId:string;id:string;action:'cancel'|'open'|'reveal'|'remove'})=>{const s=host(event),v=browserTaskInput.extend({id:z.string().uuid(),action:z.enum(['cancel','open','reveal','remove'])}).strict().parse(input);return s.downloadAction(v.taskId,v.id,v.action);},
    respondAuthentication:(event,input:{taskId:string;id:string;credentials:{user:string;pass:string}|null})=>{const s=host(event),v=browserTaskInput.extend({id:z.string().uuid(),credentials:z.object({user:z.string(),pass:z.string()}).strict().nullable()}).strict().parse(input);s.respondAuthentication(v.taskId,v.id,v.credentials);},
    respondJavascriptDialog:(event,input:{taskId:string;id:string;accept:boolean;text?:string})=>{const s=host(event),v=browserTaskInput.extend({id:z.string().uuid(),accept:z.boolean(),text:z.string().optional()}).strict().parse(input);return s.respondJavascriptDialog(v.taskId,v.id,v.accept,v.text);},
    retryAuthentication:(event,input:{taskId:string;tabId:string})=>{const s=host(event),v=browserTabInput.parse(input);return s.retryAuthentication(v.taskId,v.tabId);},
  });
}

// Destination reservation follows Orca bd9455b6165 (MIT); WillYou owns the
// task/profile lifecycle and always selects the system Downloads destination.
import {existsSync} from 'node:fs';
import {join,resolve,basename,isAbsolute} from 'node:path';
import {randomUUID} from 'node:crypto';
import type {Session,WebContents,DownloadItem} from 'electron';
import {shell} from 'electron';
import {ApplicationError} from '@shared/applications';
import {browserDownloadFilename,browserDownloadCandidate,type BrowserDownload} from '@shared/browser-downloads';
import {BrowserError} from './errors';
export class BrowserDownloadReservations {
  private readonly reserved=new Set<string>();
  constructor(private readonly directory:()=>string,private readonly exists:(path:string)=>boolean=existsSync){}
  private key(path:string){return resolve(path).normalize('NFC').toLocaleLowerCase('en-US');}
  reserve(raw:string):{name:string;path:string;release:()=>void}{
    const name=browserDownloadFilename(raw),directory=this.directory();
    for(let attempt=0;attempt<1000;attempt++){
      const candidate=browserDownloadCandidate(name,attempt),path=join(directory,candidate),key=this.key(path);
      if(this.reserved.has(key)||this.exists(path))continue;this.reserved.add(key);let released=false;
      return{name:candidate,path,release:()=>{if(!released){released=true;this.reserved.delete(key);}}};
    }
    throw new ApplicationError('RESOURCE_BUSY','无法在系统下载目录选择不重名的文件（已尝试1000次）');
  }
  explicit(path:string):{name:string;path:string;release:()=>void}{
    const key=this.key(path);if(this.reserved.has(key))throw new ApplicationError('RESOURCE_BUSY','此路径正在被另一条下载使用');this.reserved.add(key);let released=false;
    return{name:basename(path),path,release:()=>{if(!released){released=true;this.reserved.delete(key);}}};
  }
}
interface Owner {contents:WebContents;taskId:string;pageId:string;profileId:string}
interface Live {item:DownloadItem;detach:()=>void}
interface Expected {contents:WebContents;path:string;active:boolean;recordId?:string;complete:(record:BrowserDownload)=>void;fail:(error:unknown)=>void}
export class BrowserDownloads {
  private readonly owners=new Map<WebContents,Owner>();
  private readonly detachOwners=new Map<WebContents,()=>void>();
  private readonly sessions=new Map<Session,(event:Electron.Event,item:DownloadItem,contents:WebContents)=>void>();
  private readonly records=new Map<string,BrowserDownload>();
  private readonly live=new Map<string,Live>();
  private readonly expected=new Map<WebContents,Expected>();
  private readonly expectations=new Set<Expected>();
  private closed=false;
  private readonly destinations:BrowserDownloadReservations;
  constructor(private readonly options:{directory:()=>string;available:(profileId:string,taskId:string)=>boolean;changed?:(taskId:string)=>void}){this.destinations=new BrowserDownloadReservations(options.directory);}
  private changed(record:BrowserDownload){record.updatedAt=Date.now();if(!this.closed)this.options.changed?.(record.taskId);}
  install(owner:Owner):void{
    const existing=this.owners.get(owner.contents);if(existing){if(existing.taskId!==owner.taskId||existing.pageId!==owner.pageId||existing.profileId!==owner.profileId)throw Error('Download owner changed');return;}
    this.owners.set(owner.contents,owner);const destroyed=()=>{this.owners.delete(owner.contents);this.detachOwners.delete(owner.contents);for(const expected of this.expectations)if(expected.contents===owner.contents)expected.fail(new BrowserError('BROWSER_TAB_CLOSED','下载期间网页已关闭'));};owner.contents.once('destroyed',destroyed);this.detachOwners.set(owner.contents,()=>owner.contents.off('destroyed',destroyed));
    const session=owner.contents.session;if(this.sessions.has(session))return;
    const listener=(event:Electron.Event,item:DownloadItem,contents:WebContents)=>{
      const source=this.owners.get(contents);let available=false;try{available=!!source&&!source.contents.isDestroyed()&&this.options.available(source.profileId,source.taskId);}catch{/* Deny unavailable profiles. */}
      if(this.closed||!source||!available){event.preventDefault();this.expected.get(contents)?.fail(new BrowserError('BROWSER_UNAVAILABLE','下载来源页面或登录态不可用'));return;}
      const safe=<T>(read:()=>T,fallback:T):T=>{try{return read();}catch{return fallback;}};
      const pending=this.expected.get(contents),expected=pending?.active?pending:undefined;if(expected)this.expected.delete(contents);
      const id=randomUUID(),record:BrowserDownload={id,taskId:source.taskId,pageId:source.pageId,name:browserDownloadFilename(safe(()=>item.getFilename(),'download')),path:null,destination:expected?'explicit':'downloads',url:safe(()=>item.getURL(),''),state:'progress',receivedBytes:0,totalBytes:Math.max(0,safe(()=>item.getTotalBytes(),0)),updatedAt:Date.now(),error:null};this.records.set(id,record);if(expected)expected.recordId=id;
      let release=()=>{};
      try{const reservation=expected?this.destinations.explicit(expected.path):this.destinations.reserve(record.name);release=reservation.release;record.name=reservation.name;record.path=reservation.path;
        // Electron permits this only synchronously inside will-download. Do not
        // await filesystem work and accidentally open a native Save dialog.
        item.setSavePath(reservation.path);
      }catch(error){release();event.preventDefault();record.state='failed';record.error=error instanceof Error?error.message:String(error);this.changed(record);expected?.fail(error);return;}
      let finished=false;
      const readProgress=()=>{record.receivedBytes=safe(()=>item.getReceivedBytes(),record.receivedBytes);record.totalBytes=Math.max(0,safe(()=>item.getTotalBytes(),record.totalBytes));};
      const finish=(state:string,cancelNative=false)=>{
        if(finished)return;finished=true;readProgress();record.state=state==='completed'?'done':state==='cancelled'?'cancelled':'failed';record.error=state==='interrupted'?'下载连接被中断':null;record.path=safe(()=>item.getSavePath(),record.path??'')||record.path;
        item.off('updated',updated);item.off('done',done);release();this.live.delete(id);
        // Detach before cancellation: native done(cancelled) must not overwrite
        // the interruption failure or cancel an explicit expectation twice.
        if(cancelNative)try{item.cancel();}catch{/* The failed record remains usable. */}
        this.changed(record);if(record.state==='done')expected?.complete(record);else expected?.fail(new BrowserError('BROWSER_ERROR',record.state==='cancelled'?'下载已取消':'下载连接被中断'));
      };
      const updated=(_event:Electron.Event,state:string)=>{
        readProgress();this.changed(record);
        // Like Orca's download manager, defer native cancellation until outside
        // updated; resumable interruptions never emit terminal done by themselves.
        if(state==='interrupted')setImmediate(()=>{if(!finished&&!this.closed&&this.live.get(id)?.item===item&&safe(()=>item.getState()==='interrupted'&&item.canResume(),false))finish('interrupted',true);});
      };
      const done=(_event:Electron.Event,state:string)=>finish(state);
      item.on('updated',updated);item.once('done',done);this.live.set(id,{item,detach:()=>{item.off('updated',updated);item.off('done',done);release();}});this.changed(record);
    };
    session.on('will-download',listener);this.sessions.set(session,listener);
  }
  snapshot(taskId:string):BrowserDownload[]{return[...this.records.values()].filter(record=>record.taskId===taskId).reverse().map(record=>({...record}));}
  /** Arm before a guarded click; start only at its actual dispatch. The first
   * native event from this page consumes the override, never later downloads. */
  expect(contents:WebContents,path:string,signal:AbortSignal):{result:Promise<BrowserDownload>;start:()=>void;claimed:()=>boolean;cancel:(error:unknown)=>void}{
    if(this.closed||!this.owners.has(contents)||contents.isDestroyed())throw new BrowserError('BROWSER_TAB_CLOSED','网页已关闭');
    if(!isAbsolute(path)||path.includes('\0')||!basename(path))throw new ApplicationError('INVALID_INPUT','下载保存路径无效');
    if(this.expected.has(contents))throw new ApplicationError('RESOURCE_BUSY','本页已有下载正在等待触发');
    let accept!:(value:BrowserDownload)=>void,reject!:(error:unknown)=>void,settled=false;
    const result=new Promise<BrowserDownload>((yes,no)=>{accept=yes;reject=no;});void result.catch(()=>{});
    const finish=(error:unknown,record?:BrowserDownload)=>{
      if(settled)return;settled=true;if(this.expected.get(contents)===entry)this.expected.delete(contents);this.expectations.delete(entry);signal.removeEventListener('abort',aborted);
      if(record)accept({...record});else{const item=entry.recordId?this.live.get(entry.recordId)?.item:undefined;try{item?.cancel();}catch{/* Preserve the original operation failure. */}reject(error);}
    };
    const entry:Expected={contents,path,active:false,complete:record=>finish(null,record),fail:error=>finish(error)};
    const aborted=()=>entry.fail(signal.reason??new ApplicationError('CANCELED','下载操作已取消'));
    this.expected.set(contents,entry);this.expectations.add(entry);signal.addEventListener('abort',aborted,{once:true});if(signal.aborted)aborted();
    return{result,start:()=>{if(settled)throw signal.reason??new ApplicationError('CANCELED','下载操作已取消');entry.active=true;},claimed:()=>entry.recordId!==undefined,cancel:error=>entry.fail(error)};
  }
  async action(taskId:string,id:string,action:'cancel'|'open'|'reveal'|'remove'):Promise<void>{
    const record=this.records.get(id);if(!record||record.taskId!==taskId)throw new ApplicationError('SCOPE_DENIED','没有此任务的下载记录');
    if(action==='cancel'){this.live.get(id)?.item.cancel();return;}
    if(action==='remove'){if(this.live.has(id))throw new ApplicationError('RESOURCE_BUSY','请先取消正在进行的下载');this.records.delete(id);this.changed(record);return;}
    if(record.state!=='done'||!record.path)throw new ApplicationError('RESOURCE_STATE_CHANGED','下载尚未完成');
    if(action==='reveal')shell.showItemInFolder(record.path);else{const error=await shell.openPath(record.path);if(error)throw new ApplicationError('BROWSER_ERROR',error);}
  }
  dispose():void{this.closed=true;for(const expected of this.expectations)expected.fail(new BrowserError('BROWSER_UNAVAILABLE','浏览器服务已关闭'));for(const{item,detach}of this.live.values()){try{item.cancel();}catch{/* A native item may already be complete. */}detach();}for(const[session,listener]of this.sessions)session.off('will-download',listener);for(const[contents,detach]of this.detachOwners)if(!contents.isDestroyed())detach();this.live.clear();this.sessions.clear();this.owners.clear();this.detachOwners.clear();this.expected.clear();}
}

import {useEffect,useState} from 'react';
import {Download,FolderOpen,FileDown,Ban,X} from 'lucide-react';
import type {BrowserDownload} from '@shared/browser-downloads';
export type DownloadAction='cancel'|'open'|'reveal'|'remove';
/** Opening the overlay starts a viewing interval; later item changes extend it.
