/** The CLI exited but its terminal is still on screen: resume or switch from here. */
const canRestartInPlace = (task: Task) => task.archivedAt === null && !task.ptyId && tasksStore.terminals.has(task.id) && task.recovery !== 'unrecoverable';

/** Window-level title: changing the selected sidebar task never unmounts its terminal. */
export const TaskHeader = observer(function TaskHeader({ task }: { task: Task }) {
  const { t } = useTranslation();
  const { effectiveTheme, setTheme } = useTheme();
  const [busy, setBusy] = useState(false);
  const [sessionApps,setSessionApps]=useState(false);
  const headerRef = useRef<HTMLElement>(null);
  const [headerLayout, setHeaderLayout] = useState<TaskHeaderLayout>('default');
  useLayoutEffect(() => observeTaskHeaderLayout(headerRef.current, setHeaderLayout), [task.id]);
  const { requestClose, closeDialog, busy: closing } = useTaskClose(task);
  const dark = effectiveTheme === 'ydark';
  const running = Boolean(task.ptyId);
  const restart = canRestartInPlace(task) && Boolean(task.aiProfileId);
  const changeSession = async () => {
    setBusy(true);
    try {
      if (running) await rpc.tasks.kill(task.id);
      else await tasksStore.resume({ taskId: task.id });
    } catch (e) { toast.error(rpcErrorMessage(e)); }
    finally { setBusy(false); }
  };
  return <><header ref={headerRef} className="task-window-header app-drag" data-header-layout={headerLayout} data-testid="task-header">
    <div className="task-window-title" title={`${task.projectName ?? t('task.noProject')} / ${task.title}`}>
      <Folder size={17} aria-hidden="true" /><span>{task.title}</span>
    </div>
    <div className="task-window-actions app-no-drag">
      {task.projectId&&<button type="button" className="m9-file-entry" data-testid="task-new-browser" title="新建标签页（⇧⌘B）" onClick={()=>openNewBrowserTab(task.id)}><SquarePlus size={16}/><span className="task-entry-label">新建标签页</span></button>}
      <button type="button" className="m9-file-entry" data-testid="task-applications" aria-label="会话插件" onClick={()=>setSessionApps(true)}><SlidersHorizontal size={16}/><span className="task-entry-label">插件</span></button>
      <button type="button" className="m9-file-entry" data-testid="task-files" aria-pressed={navigation.filePanelOpen} onClick={() => navigation.toggleFilePanel()}><FolderOpen size={16} /><span className="task-entry-label">文件</span></button>
      <DropdownMenu>
        <DropdownMenuTrigger className="icon-button" data-testid="task-actions" aria-label={t('m6.more')} title={t('m6.more')}><Ellipsis size={18} /></DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          {(running || restart) && <>
            <DropdownMenuItem data-testid={running ? 'task-kill' : 'task-header-resume'} disabled={busy || closing || tasksStore.resuming.has(task.id) || tasksStore.closing.has(task.id)} onClick={() => void changeSession()}>
              {running ? <Square /> : <Play />}{running ? t('task.kill') : task.recovery === 'resumable' ? t('task.resume') : t('task.start')}
            </DropdownMenuItem>
            <DropdownMenuSeparator />
          </>}
          <DropdownMenuItem data-testid="task-close-session" disabled={busy || closing || tasksStore.closing.has(task.id)} onClick={requestClose}>
            <X />{t('tasks.closeSession')}
          </DropdownMenuItem>
          <DropdownMenuSeparator />
          <DropdownMenuItem onClick={() => setTheme(dark ? 'ylight' : 'ydark')}>
            {dark ? <Sun /> : <Moon />}{t('settings.theme')}
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
      {task.agentSnapshot ? <AgentTaskInfo task={task} /> : <TaskInfo task={task} />}
      <span className="task-window-divider" />
      <button type="button" className="icon-button" title={t('nav.newTask')} aria-label={t('nav.newTask')} onClick={() => navigation.newTask(task.projectId ?? undefined)}><SquarePlus size={17} /></button>
    </div>
  </header>{closeDialog}{sessionApps&&<SessionApplicationsPanel key={task.id} taskId={task.id} projectName={task.projectName} runIdentity={(task.ptyId??'stopped')+':'+(task.runtimeSnapshot?.runId??'unrecorded')} onClose={()=>setSessionApps(false)}/>}</>;
});

