          ]
        : []),
      ...(executable ? [] : ["."]),
      ...nodeModeArguments,
    ],
    { cwd, env, stdio: ["ignore", "pipe", "pipe"] },
  );
  let logs = "";
  child.stdout.on("data", (b) => {
    logs += b;
  });
  child.stderr.on("data", (b) => {
    logs += b;
  });
  let ws, mainSession;
  const closeMainInspection = () => {
    mainSession?.then(
      (session) => session.close(),
      () => {},
    );
  };
  try {
    if (startupMainHook)
      await startupMainHook({
        processId: child.pid,
        logs: () => logs,
        isRunning: () => child.exitCode === null && child.signalCode === null,
      });
    let page;
    const startupDeadline = Date.now() + 15_000;
    while (Date.now() < startupDeadline) {
      if (child.exitCode !== null || child.signalCode !== null)
        throw new Error("Electron exited before opening its test window");
      try {
        page = (
          await (
            await fetch(`http://127.0.0.1:${port}/json/list`, {
              signal: AbortSignal.timeout(
                Math.max(1, Math.min(1000, startupDeadline - Date.now())),
              ),
            })
          ).json()
        ).find((p) => p.type === "page" && (
          /^file:/.test(p.url) && /\/out\/renderer\/index\.html(?:[?#]|$)/.test(p.url) ||
          env.ELECTRON_RENDERER_URL && p.url.startsWith(env.ELECTRON_RENDERER_URL)
        ));
      } catch {
        /* starting; each request is bounded too */
      }
      if (page) break;
      await pause(100);
    }
    assert(page, "Electron debugging target not ready");
    ws = new WebSocket(page.webSocketDebuggerUrl);
    await new Promise((resolve, reject) => {
      ws.addEventListener("open", resolve, { once: true });
      ws.addEventListener("error", reject, { once: true });
    });
    let seq = 0;
    const pending = new Map();
    const cdpListeners = new Map();
    const rendererErrors = [];
    const navigationWaits = [];
    let targetCrashed = false;
    ws.addEventListener("message", ({ data }) => {
      const message = JSON.parse(data);
      if (message.id) {
        const request = pending.get(message.id);
        if (!request) return;
        clearTimeout(request.timer);
        pending.delete(message.id);
        message.error
          ? request.reject(
              Object.assign(new Error(message.error.message), {
                cdpMethod: request.method,
                cdpCode: message.error.code,
              }),
            )
          : request.resolve(message.result);
      }
      if (message.method === "Inspector.targetCrashed") targetCrashed = true;
      if (message.method === "Runtime.exceptionThrown")
        rendererErrors.push(message.params.exceptionDetails.text);
      for (const listener of cdpListeners.get(message.method) ?? [])
        listener(message.params);
    });
    ws.addEventListener("close", () => {
      for (const request of pending.values()) {
        clearTimeout(request.timer);
        request.reject(new Error("Isolated Electron target closed"));
      }
      pending.clear();
    });
    const cdp = (method, params = {}, timeoutMs = 25_000) =>
      new Promise((resolve, reject) => {
        if (ws.readyState !== WebSocket.OPEN) {
          reject(new Error("Isolated Electron target is closed"));
          return;
        }
        const id = ++seq;
        const timer = setTimeout(() => {
          pending.delete(id);
          reject(new Error(`Electron ${method} timed out`));
        }, timeoutMs);
        pending.set(id, { resolve, reject, timer, method });
        ws.send(JSON.stringify({ id, method, params }));
      });
    await cdp("Runtime.enable");
    await cdp("Inspector.enable");
    const evaluate = async (expression, timeoutMs) => {
      const result = await cdp(
        "Runtime.evaluate",
        { expression, awaitPromise: true, returnByValue: true },
        timeoutMs,
      );
      if (result.exceptionDetails)
        throw new Error(
          result.exceptionDetails.exception?.description ??
            result.exceptionDetails.text,
        );
      return result.result.value;
    };
    // Navigation retries are opt-in for read-only DOM conditions. Never replay
    // inputs, invoke calls or arbitrary evaluate expressions after navigation.
    const waitFor = async (
      expression,
      ms = 10_000,
      { navigation = false } = {},
    ) => {
      const deadline = Date.now() + ms;
      const alive = () =>
        child.exitCode === null &&
        child.signalCode === null &&
        ws.readyState === WebSocket.OPEN &&
        !targetCrashed;
      while (Date.now() < deadline) {
        if (!alive())
          throw new Error(
            "Isolated Electron target stopped during condition wait",
          );
        try {
          if (await evaluate(expression, Math.max(1, deadline - Date.now())))
            return;
        } catch (error) {
          const contextChanged =
            error.cdpMethod === "Runtime.evaluate" &&
            /^(Inspected target navigated or closed|Execution context was destroyed.*|Cannot find context with specified id.*)$/.test(
              error.message,
            );
          if (
            !navigation ||
            !contextChanged ||
            !alive() ||
            Date.now() >= deadline
          )
            throw error;
          // Confirm the original page still belongs to our original process/port.
          // A closed/crashed/replaced target is a failure, never a reattachment.
          let targets;
          try {
            targets = await (
              await fetch(`http://127.0.0.1:${port}/json/list`, {
                signal: AbortSignal.timeout(
                  Math.max(1, Math.min(1000, deadline - Date.now())),
                ),
              })
            ).json();
          } catch {
            throw error;
          }
          if (
            !alive() ||
            !targets.some(
              (target) =>
                target.id === page.id &&
                target.type === "page" &&
                target.webSocketDebuggerUrl === page.webSocketDebuggerUrl,
            )
          )
            throw error;
          navigationWaits.push({
            at: new Date().toISOString(),
            pageId: page.id,
            code: error.cdpCode,
            message: error.message,
          });
        }
        if (Date.now() < deadline)
          await pause(Math.min(100, deadline - Date.now()));
      }
      // Expressions may contain test parameters; never echo them on failure.
      throw new Error("Electron test condition timed out");
    };
    await waitFor(
      'Boolean(window.electronAPI && document.querySelector("[data-testid=nav-settings]"))',
      10_000,
      { navigation: true },
    );
    // Collectors live on the page, so a driver that reloads must call arm() again.
    const arm = () =>
      evaluate(`window.__m5 = { output: {}, exits: {} };
      window.electronAPI.eventOn('pty:data', e => { window.__m5.output[e.ptyId] = (window.__m5.output[e.ptyId] || '') + e.data; });
      window.electronAPI.eventOn('pty:exit', e => { window.__m5.exits[e.ptyId] = e.code; }); true`);
    await arm();
    const invoke = (channel, ...args) =>
      evaluate(
        `window.electronAPI.invoke(${JSON.stringify(channel)}, ...${JSON.stringify(args)})`,
        70_000,
      );
    // Test-only main-process evaluation. Enabled solely by the local launch flag above.
    // Used to compare decrypted credentials with artifacts without returning the credentials.
    const mainFailure = (response, label) => {
      const exceptionClass =
        response.result?.exceptionDetails?.exception?.className;
      const kind =
        typeof exceptionClass === "string" &&
        /^[A-Za-z][A-Za-z0-9]*$/.test(exceptionClass)
          ? exceptionClass
          : "unknown";
      const code =
        typeof response.error?.code === "number" ? response.error.code : null;
      const known = {
        "Cannot find context with specified id": "missing-context",
        "Cannot find default execution context": "missing-default-context",
        "Execution was terminated": "terminated",
        "Inspected target navigated or closed": "closed-target",
        "Runtime agent is not enabled": "runtime-disabled",
        "Internal error": "internal",
        "Promise was collected": "promise-collected",
      };
      const message = response.error?.message;
      const reason =
        typeof message === "string"
          ? (known[message] ??
            "hash-" + createHash("sha256").update(message).digest("hex"))
          : "exception";
      return new Error(
        label
          ? `Main inspection failed [${label};code=${code};class=${kind};reason=${reason}]`
          : "Credential audit could not complete inside the main process",
      );
    };
    const connectMainInspection = async () => {
      const url = /Debugger listening on (ws:\/\/127\.0\.0\.1:[^\s]+)/.exec(
        logs,
      )?.[1];
      assert(url, "Main inspector unavailable");
      const socket = new WebSocket(url),
        requests = new Map();
      let sequence = 0,
        closed = false,
        groups = 0;
      const stop = () => {
        closed = true;
        for (const request of requests.values()) {
          clearTimeout(request.timer);
          request.reject(new Error("Main inspection connection closed"));
        }
        requests.clear();
      };
      socket.addEventListener("close", stop);
      socket.addEventListener("error", stop);
      socket.addEventListener("message", ({ data }) => {
        const response = JSON.parse(data),
          request = requests.get(response.id);
        if (!request) return;
        clearTimeout(request.timer);
        requests.delete(response.id);
        request.resolve(response);
      });
      await new Promise((resolve, reject) => {
        const timer = setTimeout(
          () => reject(new Error("Main inspection connection timed out")),
          5000,
        );
        socket.addEventListener(
          "open",
          () => {
            clearTimeout(timer);
            resolve();
          },
          { once: true },
        );
        socket.addEventListener(
          "error",
          () => {
            clearTimeout(timer);
            reject(new Error("Main inspection connection failed"));
          },
          { once: true },
        );
      });
      const call = (method, params = {}, timeoutMs = 25000) =>
        new Promise((resolve, reject) => {
          if (closed || socket.readyState !== WebSocket.OPEN)
            return reject(new Error("Main inspection connection closed"));
          const id = ++sequence,
            timer = setTimeout(() => {
              requests.delete(id);
              reject(new Error("Main inspection timed out"));
            }, timeoutMs);
          requests.set(id, { resolve, reject, timer });
          socket.send(JSON.stringify({ id, method, params }));
        });
      const enabled = await call("Runtime.enable");
      if (enabled.error) {
        socket.close();
        throw mainFailure(enabled, "main-runtime-enable");
      }
      return {
        call,
        nextGroup: () => `main-eval-${++groups}`,
        close: () => {
          stop();
          socket.close();
        },
      };
    };
    const mainEvaluate = async (
      expression,
      { label, timeoutMs, synchronous = false } = {},
    ) => {
      assert(
        typeof synchronous === "boolean",
        "Main inspection mode must be explicit",
      );
      assert(
        timeoutMs === undefined ||
          (Number.isInteger(timeoutMs) && timeoutMs > 0 && timeoutMs <= 300000),
        "Explicit main inspection timeout must be bounded to300s",
      );
      const deadline =
        timeoutMs === undefined ? undefined : Date.now() + timeoutMs;
      assert(
        label === undefined || /^[a-z0-9-]{1,64}$/.test(label),
        "Inspection label must be a fixed safe operation name",
      );
      assert(
        inspectMain,
        "Main inspection was not enabled for this test instance",
      );
      assert(
        child.exitCode === null && child.signalCode === null,
        "Isolated main process already stopped",
      );
      // One session belongs to this exact App. A failed/closed session is never
      // reconnected and arbitrary evaluations are never replayed.
      mainSession ??= connectMainInspection();
      const session = await mainSession;
      const objectGroup = session.nextGroup();
      let failed = false;
      const request = (method, params) =>
        session.call(
          method,
          params,
          deadline === undefined ? 25000 : Math.max(1, deadline - Date.now()),
        );
      // Root async evaluations in this owned main until their response is read.
      // M9 synchronous observers must never start or await an async operation.
      const rootedExpression = synchronous
        ? expression
        : `(() => { const key=Symbol.for('willyou.test.main-evaluation'),pending=globalThis[key]??=new Map(),promise=Promise.resolve((0,eval)(${JSON.stringify(expression)}));pending.set(${JSON.stringify(objectGroup)},promise);return promise; })()`;
      try {
        // Retain the original remote result while converting/awaiting it. The
        // implicit awaitPromise path can lose an otherwise unreferenced promise.
        let response = await request("Runtime.evaluate", {
          expression: rootedExpression,
          awaitPromise: false,
          returnByValue: false,
          objectGroup,
        });
        if (response.error || response.result.exceptionDetails)
          throw mainFailure(response, label);
        const remote = response.result.result;
        if (synchronous && remote.subtype === "promise")
          throw new Error("Synchronous main inspection returned a promise");
        if (remote.subtype === "promise")
          response = await request("Runtime.awaitPromise", {
            promiseObjectId: remote.objectId,
            returnByValue: true,
          });
        else if (remote.objectId)
          response = await request("Runtime.callFunctionOn", {
            objectId: remote.objectId,
            functionDeclaration: "function(){return this}",
            returnByValue: true,
            objectGroup,
          });
        if (response.error || response.result.exceptionDetails)
          throw mainFailure(response, label);
        return response.result.result.value;
      } catch (error) {
        failed = true;
        throw error;
      } finally {
        try {
          if (!synchronous) {
            const cleared = await session.call(
              "Runtime.evaluate",
              {
                expression: `(() => { const key=Symbol.for('willyou.test.main-evaluation'),pending=globalThis[key];pending?.delete(${JSON.stringify(objectGroup)});if(pending?.size===0)delete globalThis[key];return true; })()`,
                returnByValue: true,
              },
              1000,
            );
            if (cleared.error || cleared.result.exceptionDetails)
              throw mainFailure(cleared, label);
          }
        } catch (error) {
          if (!failed) throw error;
        } finally {
          try {
            const released = await session.call("Runtime.releaseObjectGroup", {
              objectGroup,
            });
            if (released.error) throw mainFailure(released, label);
          } catch (error) {
            if (!failed) throw error;
          }
        }
      }
    };
    return {
      cdp,
      evaluate,
      mainEvaluate,
      waitFor,
      invoke,
      rendererErrors,
      navigationWaits,
      onCDP: (method, listener) => {
        const listeners = cdpListeners.get(method) ?? new Set();
        listeners.add(listener);
        cdpListeners.set(method, listeners);
        return () => {
          listeners.delete(listener);
          if (!listeners.size) cdpListeners.delete(method);
        };
      },
      processId: child.pid,
      waitForExit: (timeoutMs = 15_000) => {
        closeMainInspection();
        return new Promise((resolve, reject) => {
          const result = () => ({
            pid: child.pid,
            code: child.exitCode,
            signal: child.signalCode,
          });
          if (child.exitCode !== null || child.signalCode !== null) {
            resolve(result());
            return;
          }
          const onExit = () => {
            clearTimeout(timer);
            resolve(result());
          };
          const timer = setTimeout(() => {
            child.off("exit", onExit);
            reject(new Error("Isolated App did not finish its normal exit"));
          }, timeoutMs);
          child.once("exit", onExit);
        });
      },
      crash: async () => {
        closeMainInspection();
        assert(
          child.exitCode === null && child.signalCode === null,
          "Test App is already stopped",
        );
        const exited = new Promise((resolve) =>
          child.once("exit", (code, signal) =>
            resolve({ pid: child.pid, code, signal }),
          ),
        );
        assert(child.kill("SIGKILL"), "Could not stop this isolated test App");
        return await Promise.race([
          exited,
          pause(3000).then(() => {
            throw new Error("Test App crash did not finish");
          }),
        ]);
      },
      arm,
      output: (ptyId) =>
        evaluate(`window.__m5?.output[${JSON.stringify(ptyId)}] ?? ''`),
      input: (ptyId, data) =>
        evaluate(
          `window.electronAPI.eventSend('pty:input', ${JSON.stringify({ ptyId, data })})`,
        ),
      screenshot: async (path) => {
        const { data } = await cdp("Page.captureScreenshot", { format: "png" });
        await writeFile(path, Buffer.from(data, "base64"), { mode: 0o600 });
      },
      logs: () => logs,
      close: async () => {
        closeMainInspection();
        for (const item of pending.values()) {
          clearTimeout(item.timer);
          item.reject(new Error("Electron test closed"));
        }
        pending.clear();
        ws.close();
        cdpListeners.clear();
        if (child.exitCode === null && child.signalCode === null) {
          const done = new Promise((r) => child.once("exit", r));
          child.kill("SIGTERM");
          await Promise.race([done, pause(3000)]);
          if (child.exitCode === null && child.signalCode === null)
            child.kill("SIGKILL");
        }
      },
    };
  } catch (error) {
    closeMainInspection();
    ws?.close();
    child.kill("SIGKILL");
    if (error && typeof error === "object") {
      error.electronStartupLogs = logs;
      error.electronStartupProcess = {
        pid: child.pid,
        code: child.exitCode,
        signal: child.signalCode,
      };
    }
    throw error;
  }
}

// Explicit M13 acceptance namespace, shared by the pre-entry home fixture and
// launcher. Never enables hooks for a daily App or mismatched private run.
export function isM13HomePath(home){
 return typeof home==='string'&&/^\/private\/tmp\/willyou-m13-p1-App[0-9]{3}-ui-[0-9]{3}\/home$/.test(home);
}
export function isM13PreEntryRun(executable,userData,home){
 if(typeof executable!=='string')return false;
 const match=/^\/private\/tmp\/willyou-m13-p1-(App[0-9]{3})\/(?:baseline\/)?mac-arm64\/WillYou\.app\/Contents\/MacOS\/WillYou$/.exec(executable);
 if(!match||!isM13HomePath(home))return false;
 const run=new RegExp('^/private/tmp/willyou-m13-p1-'+match[1]+'-ui-[0-9]{3}/userdata$');
 return typeof userData==='string'&&run.test(userData)&&home===userData.replace(/\/userdata$/,'/home');
}

// Window chrome follows Yoda (Apache-2.0) src/main/app/window.ts.
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { app, BrowserWindow, nativeTheme, type IpcMainEvent } from 'electron';
import type { Theme } from '@shared/app-settings';
import { appIcon } from './icon';

let mainWindow: BrowserWindow | null = null;
let mainDocumentURL: string | null = null;
let appQuitting = false;
const MAC_TITLEBAR_HEIGHT = 40;

/** Once a real quit starts, the last window stops hiding and actually closes. */
export function markAppQuitting(): void {
  appQuitting = true;
}

export function getMainWindow(): BrowserWindow | null {
  return mainWindow && !mainWindow.isDestroyed() ? mainWindow : null;
}

/** A renderer navigation must not carry terminal authority to another page. */
export function isMainRenderer(event: Pick<IpcMainEvent, 'sender' | 'senderFrame'>): boolean {
  const win = getMainWindow();
  if (!win || event.sender !== win.webContents || event.sender.isDestroyed() ||
      !event.senderFrame || event.senderFrame !== event.sender.mainFrame || !mainDocumentURL) return false;
  try {
    const current = new URL(event.senderFrame.url);
    current.hash = '';
    return current.href === mainDocumentURL;
  } catch { return false; }
}

/** Native chrome (menus, dialogs, window background) follows the theme setting. */
export function applyNativeTheme(theme: Theme | null): void {
  nativeTheme.themeSource = theme === null ? 'system' : theme === 'ydark' ? 'dark' : 'light';
}

function windowBackground(): string {
  return nativeTheme.shouldUseDarkColors ? '#111111' : '#ffffff';
}

export async function createMainWindow(): Promise<BrowserWindow> {
  const isMac = process.platform === 'darwin';
  const win = new BrowserWindow({
    width: 1400,
    height: 900,
    minWidth: 700,
    minHeight: 500,
    title: 'WillYou',
    icon: appIcon,
    show: false,
    backgroundColor: windowBackground(),
    ...(isMac
      ? {
          titleBarStyle: 'hiddenInset' as const,
          titleBarOverlay: { height: MAC_TITLEBAR_HEIGHT },
          trafficLightPosition: { x: 14, y: 14 },
          acceptFirstMouse: true,
        }
      : {}),
    webPreferences: {
      preload: join(__dirname, '../preload/index.js'),
      sandbox: false,
      contextIsolation: true,
      nodeIntegration: false,
      // Keep terminal painting and renderer state current when the workspace is
      // covered by another window; PTY sessions continue to run in the background.
      backgroundThrottling: false,
    },
  });
  mainWindow = win;
  const documentURL = new URL(process.env.ELECTRON_RENDERER_URL || pathToFileURL(join(__dirname, '../renderer/index.html')).href);
  documentURL.hash = '';
  mainDocumentURL = documentURL.href;

  // macOS: closing the window hides it (terminals keep running); Cmd+Q is the real quit.
  win.on('close', (event) => {
    if (appQuitting) return;
    event.preventDefault();
    if (isMac) win.hide();
    else app.quit();
  });
  win.on('closed', () => {
    if (mainWindow === win) { mainWindow = null; mainDocumentURL = null; }
  });
  win.once('ready-to-show', () => win.show());

  if (process.env.ELECTRON_RENDERER_URL) await win.loadURL(process.env.ELECTRON_RENDERER_URL);
  else await win.loadFile(join(__dirname, '../renderer/index.html'));
  return win;
}

import { readFile } from 'node:fs/promises';
import { homedir } from 'node:os';
import { join } from 'node:path';
import { type AiProfileInput } from '@shared/ai-profiles';
import { createRPCController } from '@shared/ipc/rpc';
import type { Runner } from '@shared/types';
import { PARENT_AGENT_VARS } from '../../launch-env';
import type { AiProfileService } from './ai-profile-service';
import type { ProfileHealth } from './profile-health';

const defaultZshrc = () => join(homedir(), '.zshrc');

// The file is read here in main and never sent to the renderer: only the masked preview leaves.
async function readRc(path?: string | null): Promise<string> {
  const file = path?.trim() || defaultZshrc();
  try {
    return await readFile(file, 'utf8');
  } catch (e) {
    throw new Error(`读取 ${file} 失败：${(e as NodeJS.ErrnoException).code ?? (e as Error).message}`);
  }
}

export function createAiProfileController(svc: AiProfileService, health: ProfileHealth, baseEnv: () => Record<string, string>) {
  const detectEnv = () => {
    const env = { ...baseEnv() };
    for (const k of PARENT_AGENT_VARS) delete env[k];
    return env;
  };
  return {
    aiProfiles: createRPCController({
      list: () => svc.list().map((v) => health.withChecking(v)),
      get: (id: string) => health.withChecking(svc.get(id)),
      // Auto tests run after import / create / an edit that changes how the CLI starts — never at startup.
      create: (input: AiProfileInput) => {
        const view = svc.create(input);
        health.testInBackground(view.id, 'auto');
        return health.withChecking(view);
      },
      update: (id: string, input: AiProfileInput) => {
        const before = svc.launchSignature(id);
        const view = svc.update(id, input);
        if (svc.launchSignature(id) !== before) health.testInBackground(id, 'auto');
        return health.withChecking(view);
      },
      test: (id: string) => health.test(id, 'manual'),
      delete: (id: string) => svc.delete(id),
      setDefault: (id: string) => svc.setDefault(id),
      defaultZshrcPath: () => defaultZshrc(),
      previewZshrc: async (path?: string | null) => svc.previewZshrc(await readRc(path)),
      importZshrc: async (path: string | null, accounts: string[]) => {
        const r = svc.importZshrc(await readRc(path), accounts);
        for (const v of r.created) health.testInBackground(v.id, 'auto');
        return { ...r, created: r.created.map((v) => health.withChecking(v)) };
      },
      detectRunners: () => Promise.all(svc.runnerAdapters.list().map(async adapter => ({ runner: adapter.id, ...await adapter.discoverExecutable(null, { env: detectEnv() }) }))),
      detectRunner: async (runner: Runner, executable: string | null) => ({ runner, ...await svc.runnerAdapters.get(runner).discoverExecutable(executable, { env: detectEnv() }) }),
    }),
  };
}

import { spawn } from 'node:child_process';
import { randomBytes } from 'node:crypto';
