// One real round trip: the profile's CLI, started exactly like a task (login shell, profile
// variables re-exported after the rc files), asked to echo a random code. Non-interactive flags
// as in Yoda's rewritePrompt.ts; nothing is saved to the CLI's session history, and the empty
// project folder Claude still creates for the check directory is removed afterwards.

export const TEST_TIMEOUT_MS = 60_000;
const OUTPUT_MAX = 64 * 1024;

export interface ProfileTestResult {
  category: ProfileCheckCategory;
  message: string;
  ms: number;
}

export function testArgs(runner: Runner, profileArgs: string[], prompt: string): string[] {
  if (runner === 'claude') return [...profileArgs, '--print', '--no-session-persistence', '--output-format', 'text', prompt];
  if (runner !== 'codex') throw new Error('当前运行器尚未登记自动连通性测试；可核验版本并启动原生任务');
  return [...profileArgs, 'exec', '--ephemeral', '--sandbox', 'read-only', '--skip-git-repo-check', '--color', 'never', prompt];
}

/**
 * Claude retries even a 401 for minutes before giving up, which would read as a timeout here;
 * one attempt is enough for a check. A value set in the profile itself still wins.
 */
const TEST_ENV: Record<Runner, Record<string, string>> = {
  claude: { CLAUDE_CODE_MAX_RETRIES: '0' },
  codex: {},
};

/** Whether the tree holds nothing but (empty) directories. */
function onlyDirs(dir: string): boolean {
  return readdirSync(dir, { withFileTypes: true }).every((e) => e.isDirectory() && onlyDirs(join(dir, e.name)));
}

/**
 * Even with --no-session-persistence Claude creates <config>/projects/<cwd>/memory/ for the
 * check directory. Remove it — but only while it holds no file, so nothing real is ever lost.
 */
export function removeClaudeTrace(configDir: string, cwds: string[]): void {
  for (const cwd of new Set(cwds)) {
    const dir = join(configDir, 'projects', encodeClaudeDir(cwd));
    try {
      if (existsSync(dir) && onlyDirs(dir)) rmSync(dir, { recursive: true });
    } catch {
      // Best effort: a leftover empty folder is harmless.
    }
  }
}

export interface TestDeps {
  baseEnv: Record<string, string>;
  timeoutMs?: number;
  shell?: string;
  /** Only for tests: a fixed code instead of a random one. */
  code?: string;
}

export function runProfileTest(profile: ResolvedProfile, secrets: string[], d: TestDeps): Promise<ProfileTestResult> {
  if (profile.runner !== 'claude' && profile.runner !== 'codex') return Promise.resolve({ category: 'unexpected', message: '当前运行器的自动连通性测试尚未验证；可核验版本并启动原生任务', ms: 0 });
  const code = d.code ?? `SMARTDD-OK-${randomBytes(4).toString('hex')}`;
  const prompt = `This is an automated connectivity check. Do not use any tools. Reply with exactly ${code} and nothing else.`;
  const base = { ...d.baseEnv };
  for (const k of PARENT_AGENT_VARS) delete base[k];
  const plan = planLaunchEnv(base, { ...TEST_ENV[profile.runner], ...profile.env }, profile.isolatePrefixes);
  const { file, args } = shellWrapped(profile.command, testArgs(profile.runner, profile.args, prompt), plan.scriptArgs, d.shell);
  const timeoutMs = d.timeoutMs ?? TEST_TIMEOUT_MS;
  // An empty directory: no project instructions, nothing for the CLI to trust or touch.
  const cwd = mkdtempSync(join(tmpdir(), 'smartdd-check-'));
  // Claude names its project folder after the resolved path (/var → /private/var on macOS).
  const cwds = [cwd, realpathSync(cwd)];
  const started = Date.now();
  const scrub = (s: string) => redact(s, secrets);

  return new Promise((resolve) => {
    let stdout = '';
    let stderr = '';
    let timedOut = false;
    let settled = false;
    const finish = (r: Omit<ProfileTestResult, 'ms'>) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      rmSync(cwd, { recursive: true, force: true });
      if (profile.runner === 'claude') removeClaudeTrace(stateRootFor('claude', profile.env, base), cwds);
      resolve({ ...r, message: scrub(r.message), ms: Date.now() - started });
    };
    // Own process group, so a timeout also stops what the shell started.
    const child = spawn(file, args, { cwd, env: plan.env, stdio: ['ignore', 'pipe', 'pipe'], detached: true });
    const take = (cur: string, chunk: Buffer) => (cur.length < OUTPUT_MAX ? cur + chunk.toString('utf8') : cur);
    child.stdout.on('data', (c: Buffer) => (stdout = take(stdout, c)));
    child.stderr.on('data', (c: Buffer) => (stderr = take(stderr, c)));
    const timer = setTimeout(() => {
      timedOut = true;
      try {
        if (child.pid) process.kill(-child.pid, 'SIGKILL');
      } catch {
        child.kill('SIGKILL');
      }
    }, timeoutMs);
    child.on('error', (e) => finish({ category: 'other', message: `无法启动 ${file}：${e.message}` }));
    child.on('close', (exitCode) => {
      // Only stdout counts: Codex echoes the prompt, code included, on stderr.
      if (stdout.includes(code)) return finish({ category: 'ok', message: '' });
      const reason = pickReason(stdout, stderr, code);
      if (timedOut) return finish({ category: 'timeout', message: `${Math.round(timeoutMs / 1000)} 秒内没有回复${reason ? `：${reason}` : ''}` });
      // The shell's own answer when exec finds nothing: 127.
      if (exitCode === 127) {
        return finish({ category: 'not_found', message: `找不到命令 ${profile.command}${reason ? `：${reason}` : ''}` });
      }
      if (exitCode === 0) return finish({ category: 'unexpected', message: `有回复，但内容不是校验码：${reason || '（空）'}` });
      return finish({ category: classifyText(reason) ?? 'other', message: reason || `退出码 ${exitCode}` });
    });
  });
}

import { execFile } from 'node:child_process';
import type { RunnerInfo } from '@shared/ai-profiles';
import { RUNNERS } from '@shared/ai-profiles';
import type { Runner } from '@shared/types';
import { loginShell } from '../../pty-manager';

// Resolve and version-check in the same login+interactive shell the terminal uses, so the
// answer matches what a task will actually run (Finder-launched apps have a bare PATH).
// Markers separate our output from whatever the rc files print. A PATH-only lookup (not
// `command -v`, which reports aliases) matches the launch, where `exec` skips aliases too.
const DETECT_SCRIPT = [
  'printf "__SMARTDD_SHELL_PATH__%s\\n" "$PATH"',
  'if [ -n "$ZSH_VERSION" ]; then p=$(whence -p -- "$1" 2>/dev/null); else p=$(type -P -- "$1" 2>/dev/null); fi',
  '[ -n "$p" ] || { printf "__SMARTDD_MISSING__\\n"; exit 0; }',
  'case "$p" in /*) ;; *) printf "__SMARTDD_MISSING__\\n"; exit 0;; esac',
  'printf "__SMARTDD_PATH__%s\\n" "$p"',
  '"$p" --version 2>&1 | command head -n 3',
].join('\n');

export interface DetectOptions {
  env: Record<string, string>;
  shell?: string;
  timeoutMs?: number;
  signal?: AbortSignal;
}

/** Parse the script output; exported for tests. */
export function parseDetectOutput(runner: Runner, command: string, stdout: string): RunnerInfo {
  const lines = stdout.split(/\r?\n/);
  const at = lines.findIndex((l) => l.startsWith('__SMARTDD_PATH__') || l.startsWith('__SMARTDD_MISSING__'));
  if (at === -1 || lines[at].startsWith('__SMARTDD_MISSING__')) {
    return { runner, command, path: null, version: null, error: `找不到 ${command}，请确认已安装，或在配置中手工指定路径` };
  }
  const path = lines[at].slice('__SMARTDD_PATH__'.length).trim();
  const version = lines
    .slice(at + 1)
    .map((l) => l.trim())
    .find(Boolean);
  return version
    ? { runner, command, path, version, error: null }
    : { runner, command, path, version: null, error: `${command} --version 没有输出` };
}

/** detectRunner plus the login shell's PATH, which every later native step must share with the launch. */
export async function detectNativeCli(runner: Runner, executable: string | null, o: DetectOptions): Promise<RunnerInfo & { shellPath: string | null }> {
  const { info, stdout } = await runDetect(runner, executable, o);
  const line = stdout.split(/\r?\n/).find((l) => l.startsWith('__SMARTDD_SHELL_PATH__'));
  return { ...info, shellPath: line ? line.slice('__SMARTDD_SHELL_PATH__'.length) : null };
}

export async function detectRunner(runner: Runner, executable: string | null, o: DetectOptions): Promise<RunnerInfo> {
  return (await runDetect(runner, executable, o)).info;
}

function runDetect(runner: Runner, executable: string | null, o: DetectOptions): Promise<{ info: RunnerInfo; stdout: string }> {
  const command = executable?.trim() || RUNNERS[runner].command;
  return new Promise((resolve) => {
    execFile(
      o.shell ?? loginShell(),
      ['-l', '-i', '-c', DETECT_SCRIPT, 'smartdd-detect', command],
      { env: o.env, timeout: o.timeoutMs ?? 15_000, maxBuffer: 1024 * 1024, signal: o.signal },
      (err, stdout) => {
        const text = String(stdout ?? ''), info = parseDetectOutput(runner, command, text);
        if (err && !info.path) {
          const timedOut = (err as NodeJS.ErrnoException & { killed?: boolean }).killed;
          resolve({ info: { ...info, error: timedOut ? `检测 ${command} 超时` : (info.error ?? err.message) }, stdout: text });
        } else resolve({ info, stdout: text });
      }
    );
  });
}

import {execFile} from 'node:child_process';
import {createRequire} from 'node:module';
import {accessSync,constants,lstatSync,openSync,readSync,closeSync,readFileSync,realpathSync} from 'node:fs';
import {dirname,join} from 'node:path';
import {ApplicationError} from '@shared/applications';
import {PARENT_AGENT_VARS,VALUE_PREFIX} from '../../launch-env';
